import java.util.*;

class Solution {
    private Map<Long, Integer> count;
    private int res;

    public int pathSum(TreeNode root, int target) {
        count = new HashMap<>();
        count.put(0L, 1);                    // empty prefix
        res = 0;
        go(root, 0L, target);
        return res;
    }

    private void go(TreeNode n, long s, int target) {
        if (n == null) return;
        s += n.val;
        res += count.getOrDefault(s - target, 0); // runs ending at n
        count.put(s, count.getOrDefault(s, 0) + 1);
        go(n.left, s, target);
        go(n.right, s, target);
        count.put(s, count.get(s) - 1);           // undo before going back up
    }
}

